<?php require __DIR__.'/../includes/functions.php'; require_admin(); $leads=lead_rows(); $content=json_encode(load_content(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE); ?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="../assets/styles.css"></head><body class="admin-bg"><main class="admin-wrap"><div class="admin-head"><div><h1>Website Admin</h1><p>Manage enquiries and edit website content.</p></div><div><a class="btn ghost" href="../index.php">View site</a><a class="btn ghost" href="logout.php">Logout</a></div></div><?php if(!empty($_SESSION['flash'])): ?><div class="success-msg"><?=h($_SESSION['flash']); unset($_SESSION['flash']);?></div><?php endif; ?><section class="admin-card"><h2>Leads</h2><p>Total enquiries: <strong><?=count($leads)?></strong> <a href="export.php">Export CSV</a></p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Name</th><th>Phone</th><th>Business</th><th>Service</th><th>Budget</th><th>Message</th></tr></thead><tbody><?php foreach(array_slice($leads,0,50) as $l): ?><tr><td><?=h($l['created_at']??'')?></td><td><?=h($l['name']??'')?></td><td><?=h($l['phone']??'')?></td><td><?=h($l['business']??'')?></td><td><?=h($l['service']??'')?></td><td><?=h($l['budget']??'')?></td><td><?=h($l['message']??'')?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="admin-card" id="content"><h2>Edit website content</h2><p>Edit carefully. This is JSON. Invalid JSON will not save.</p><form method="post" action="save-content.php"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><textarea class="json-editor" name="content_json"><?=h($content)?></textarea><button class="btn primary">Save content</button></form></section></main></body></html>